breach.segment:
WHERE marker > 0
// Deliberate states that are not outages: RUNNABLE = stopped by the owner, PENDING_CREATE = being provisioned.
// Remove a state from this list to alert on it as well, or add "MAINTENANCE" to ignore planned maintenance.
| WHERE COALESCE(current_state, "") NOT IN ("RUNNABLE", "PENDING_CREATE")
// Breach: latest state is not RUNNING (MAINTENANCE, FAILED, SUSPENDED, UNKNOWN_STATE), or RUNNING but up = 0
| WHERE current_state != "RUNNING" OR up_latest == 0
// Persistence: at least 3 observed down minutes in the last 10 minutes, so a single blip is left to the restart rule
| WHERE down_minutes >= 3
| EVAL outage_type = CASE(
    current_state == "MAINTENANCE", "planned maintenance",
    current_state IS NULL OR current_state == "RUNNING", "not accepting connections",
    "unplanned")
| SORT database_id ASC
// Up to 1000 breaching instances per run (the ES|QL default row limit); raise it for larger fleets
| LIMIT 1000
| KEEP database_id, current_state, up_latest, outage_type, down_minutes, last_sample
